@startuml

class Organizer {
  + firstName : string
  + lastName : string
  + email : string
  + postalAddress : string
  + phoneNumber : string
  + password : string
}

class EventType {
  + name : string
}

class Event {
  + occasion : string
  + startDateTime : datetime
  + endDateTime : datetime
}

class Location {
  + name : string
  + address : string
}

class Attendee {
  + firstName : string
  + lastName : string
  + email : string
  + password : string
  + attendanceStatus : string
}

class Task {
  + description : string
  + status : string
}

class TaskAssignment {
}

class Invitation {
}

Organizer "1..*" -- "1..*" Event : organizes
Organizer "0..*" -- "0..*" Event : attends
Event "1" -- "1" EventType
Event "1" -- "1" Location
Event "1" -- "0..*" Task
Event "1" -- "0..*" Invitation
Invitation "1" -- "1" Attendee
Attendee "0..*" -- "0..*" TaskAssignment : selects
Task "1" -- "0..*" TaskAssignment : is assigned to

@enduml

